from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==2 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c));comp=[]
   while q:
    a,b=q.pop();comp.append((a,b))
    for x,y in [(a+1,b),(a-1,b),(a,b+1),(a,b-1)]:
     if 0<=x<R and 0<=y<C and grid[x][y]==2 and (x,y) not in seen:seen.add((x,y));q.append((x,y))
   comps.append(comp)
print(len(comps), sorted([len(x) for x in comps],reverse=True)[:20])
